-- Create enum type "case_interruption_reason_t"
CREATE TYPE "case_interruption_reason_t" AS ENUM ('timeout', 'cpu_limit', 'memory_limit', 'stack_limit', 'file_size_limit', 'signal', 'monitor_error', 'output_error', 'server_error');
-- Modify "commits_exercise_test_cases_results" table
ALTER TABLE "commits_exercise_test_cases_results" ADD COLUMN "reason" "case_interruption_reason_t" NULL;
-- Create "commit_test_case_limits" table
CREATE TABLE "commit_test_case_limits" ("commit_id" integer NOT NULL, "exercise_test_case_id" integer NOT NULL, "cpu_time_limit_seconds" integer NOT NULL, "mem_usage_limit_bytes" bigint NOT NULL, "stack_limit_bytes" bigint NOT NULL, "file_size_limit_bytes" bigint NOT NULL, PRIMARY KEY ("commit_id", "exercise_test_case_id"), CONSTRAINT "commit_test_case_limits_commit_id_fkey" FOREIGN KEY ("commit_id") REFERENCES "commits" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "commit_test_case_limits_exercise_test_case_id_fkey" FOREIGN KEY ("exercise_test_case_id") REFERENCES "exercises_test_cases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create "exercise_language_limits" table
CREATE TABLE "exercise_language_limits" ("exercise_id" integer NOT NULL, "allowed_file_type_id" integer NOT NULL, "cpu_time_limit_seconds" integer NULL, "mem_usage_limit_bytes" bigint NULL, "stack_limit_bytes" bigint NULL, "file_size_limit_bytes" bigint NULL, PRIMARY KEY ("exercise_id", "allowed_file_type_id"), CONSTRAINT "exercise_language_limits_allowed_file_type_id_fkey" FOREIGN KEY ("allowed_file_type_id") REFERENCES "allowed_file_types" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "exercise_language_limits_exercise_id_fkey" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create "exercise_limit_alerts" table
CREATE TABLE "exercise_limit_alerts" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "exercise_id" integer NOT NULL, "allowed_file_type_id" integer NULL, "limit_name" text NOT NULL, "failures" integer NOT NULL, "window_started_at" timestamptz NOT NULL, "window_ended_at" timestamptz NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "acknowledged_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "exercise_limit_alerts_allowed_file_type_id_fkey" FOREIGN KEY ("allowed_file_type_id") REFERENCES "allowed_file_types" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "exercise_limit_alerts_exercise_id_fkey" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create "test_case_language_limits" table
CREATE TABLE "test_case_language_limits" ("exercise_test_case_id" integer NOT NULL, "allowed_file_type_id" integer NOT NULL, "cpu_time_limit_seconds" integer NULL, "mem_usage_limit_bytes" bigint NULL, "stack_limit_bytes" bigint NULL, "file_size_limit_bytes" bigint NULL, PRIMARY KEY ("exercise_test_case_id", "allowed_file_type_id"), CONSTRAINT "test_case_language_limits_allowed_file_type_id_fkey" FOREIGN KEY ("allowed_file_type_id") REFERENCES "allowed_file_types" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "test_case_language_limits_exercise_test_case_id_fkey" FOREIGN KEY ("exercise_test_case_id") REFERENCES "exercises_test_cases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);

-- Move the explicit per-case limits to per-language overrides: a case that set a
-- limit used to apply it to every language it ran under, so it becomes one
-- override per allowed language. Unset (0) limits now inherit the platform
-- default instead of an image default that no longer exists.
INSERT INTO "test_case_language_limits" ("exercise_test_case_id", "allowed_file_type_id", "cpu_time_limit_seconds", "mem_usage_limit_bytes", "stack_limit_bytes", "file_size_limit_bytes")
SELECT tc."id",
       eaft."allowed_file_type_id",
       CASE WHEN tc."cpu_time_limit_seconds" > 0 THEN tc."cpu_time_limit_seconds" END,
       CASE WHEN tc."mem_usage_limit_bytes" > 0 THEN tc."mem_usage_limit_bytes" END,
       CASE WHEN tc."stack_limit_bytes" > 0 THEN tc."stack_limit_bytes" END,
       CASE WHEN tc."file_size_limit_bytes" > 0 THEN tc."file_size_limit_bytes" END
FROM "exercises_test_cases" tc
JOIN "exercises_allowed_file_types" eaft ON eaft."exercise_id" = tc."exercise_id"
WHERE tc."cpu_time_limit_seconds" <> 0
   OR tc."mem_usage_limit_bytes" <> 0
   OR tc."stack_limit_bytes" <> 0
   OR tc."file_size_limit_bytes" <> 0
ON CONFLICT DO NOTHING;

-- Modify "exercises_test_cases" table
ALTER TABLE "exercises_test_cases" DROP COLUMN "cpu_time_limit_seconds", DROP COLUMN "mem_usage_limit_bytes", DROP COLUMN "stack_limit_bytes", DROP COLUMN "file_size_limit_bytes";

-- Row level security for the new tables, kept in step with the rest of the schema.
ALTER TABLE "commit_test_case_limits" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "runcodes_app_only" ON "commit_test_case_limits" TO PUBLIC
  USING (current_user = 'runcodes_app')
  WITH CHECK (current_user = 'runcodes_app');

ALTER TABLE "exercise_language_limits" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "runcodes_app_only" ON "exercise_language_limits" TO PUBLIC
  USING (current_user = 'runcodes_app')
  WITH CHECK (current_user = 'runcodes_app');

ALTER TABLE "exercise_limit_alerts" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "runcodes_app_only" ON "exercise_limit_alerts" TO PUBLIC
  USING (current_user = 'runcodes_app')
  WITH CHECK (current_user = 'runcodes_app');

ALTER TABLE "test_case_language_limits" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "runcodes_app_only" ON "test_case_language_limits" TO PUBLIC
  USING (current_user = 'runcodes_app')
  WITH CHECK (current_user = 'runcodes_app');
